 const c=dom[0]||approved.find(x=>!x.source.startsWith('footerLineDOM'));
 if(c){const lineSource=c.source.startsWith('footerLineDOM')?'footerLineDOM':c.source.startsWith('footerLineUnverifiedDOM')?'footerLineUnverifiedDOM':'footerLineText';return{ok:true,lineGroups:c.lineGroups,line:c.lineGroups.map(g=>g.join('-')).join(' / '),lineSeq:c.lineGroups.flat().join('-'),lineSource,source:c.source,raw:c.raw,warnings:diagnostics,diagnostics,originVerified};}
